package oracle;import java.io.*;import java.util.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;import core.game.world.map.build.ChunkFlags;
public class Support{
 static ChunkFlags chunk;static Map<String,Integer[]> tables;static List<Object> events;static Map<String,Integer> calls;static List<Map> hooks;static int[] base;
 static int n(Object v){return((Number)v).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}
 public static class Failure extends RuntimeException{}
 static void emit(String name,Object...args){List<Object> row=new ArrayList<>();row.add(name);Collections.addAll(row,args);events.add(row);int call=calls.merge(name,1,Integer::sum);for(Map h:hooks)if(name.equals(h.get("event"))&&call==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}
 public static Integer[] flags(int key,boolean p){emit("flags",key,p);return tables.computeIfAbsent((p?"p:":"m:")+key,k->{Integer[] a=new Integer[64];Arrays.fill(a,p?0:-1);return a;});}
 public static void border(int z,int x,int y,boolean p,int mask,boolean add){emit("border",x,y,z,p,mask,add);Integer[] a=flags((z<<22)|((x>>3)<<11)|(y>>3),p);int i=(x&7)*8+(y&7);if(add)a[i]=Math.max(0,a[i])|mask;else if((a[i]&mask)!=0)a[i]=Math.max(0,a[i])&~mask;}
 static Object act(Map a){String op=(String)a.get("op");int x=v(a,"x",0),y=v(a,"y",0),mask=v(a,"mask",0);boolean add=!Boolean.FALSE.equals(a.get("add"));switch(op){
 case "get":return chunk.getFlag(x,y);case "flag":if(add)chunk.flag(x,y,mask);else chunk.unflag(x,y,mask);break;
 case "addFlag":chunk.addFlag(x,y,mask);break;case "removeFlag":chunk.removeFlag(x,y,mask);break;case "clear":chunk.clearFlag(x,y);break;case "invalidate":chunk.invalidateFlag(x,y);break;
 case "door":if(add)chunk.flagDoorObject(x,y,v(a,"rotation",0),v(a,"shape",0),b(a,"clipped"));else chunk.unflagDoorObject(x,y,v(a,"rotation",0),v(a,"shape",0),b(a,"clipped"));break;
 case "solid":if(add)chunk.flagSolidObject(x,y,v(a,"sx",1),v(a,"sy",1),b(a,"clipped"));else chunk.unflagSolidObject(x,y,v(a,"sx",1),v(a,"sy",1),b(a,"clipped"));break;
 case "tile":if(add)chunk.flagTileObject(x,y);else chunk.unflagTileObject(x,y);break;case "empty":chunk.flagEmptyTile(x,y);break;case "solidTile":chunk.flagSolidTile(x,y);break;
 case "members":chunk.setMembers(b(a,"value"));break;case "landscape":chunk.setLandscape(null);break;case "fail":throw new Failure();default:throw new IllegalArgumentException(op);
 }return null;}
 static Object snapshot(Object result,String error){Map<String,Object> m=new TreeMap<>();Map<String,Object> fs=new TreeMap<>();for(String key:tables.keySet())fs.put(key,Arrays.asList(tables.get(key).clone()));List<Object> land=null;if(chunk.getLandscape()!=null){land=new ArrayList<>();for(boolean[] row:chunk.getLandscape()){List<Boolean> r=new ArrayList<>();for(boolean b:row)r.add(b);land.add(r);}}m.put("flags",fs);m.put("landscape",land);m.put("members",chunk.isMembers());m.put("baseZ",chunk.getBaseZ());m.put("events",new ArrayList<>(events));m.put("result",result);m.put("error",error);return m;}
 public static void main(String[] args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){JSONObject c=(JSONObject)new JSONParser().parse(line);List a=(List)c.getOrDefault("base",Arrays.asList(3200,3216,0));chunk=new ChunkFlags(n(a.get(0)),n(a.get(1)),n(a.get(2)),b(c,"projectile"));tables=new TreeMap<>();events=new ArrayList<>();calls=new HashMap<>();hooks=(List<Map>)c.getOrDefault("hooks",new ArrayList<>());List<Object> out=new ArrayList<>();for(Object action:(List)c.get("actions")){events.clear();Object result=null;String failure=null;try{result=act((Map)action);}catch(Failure e){failure="Binding";}catch(IndexOutOfBoundsException e){failure="Index";}out.add(snapshot(result,failure));}c.put("expected",out);System.out.println(JSONValue.toJSONString(c));}}}
}
